 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 evidence={'build':'1002h1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'scope':'BTC-only development; halving18-30month direction confirmed by past price; no accepted increment versus price and clock controls; no accepted strategy'};(DOWN/'btc-phase-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-phase-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-phase-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_phase_study.py','test_btc_phase_study.py','verify_btc_phase_study.py','reproduce_btc_phase_study.py','btc_target_ledger.py','btc_session_study.py','btc_persistence_study.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,2,0,0,0)),p.read_bytes())
