 files=['btc-phase-research.html','btc-web-research.html','downloads/btc-phase-evidence.zip','downloads/btc-phase-evidence.json','downloads/btc-phase-summary.csv','EXPERIMENT_BTC_PHASE_20261002.md','BTC_WEB_RESEARCH_20261002.md','assets/btc-continuation.css','assets/icon.svg'];out=ROOT/'runs/btc-phase-report-20261002';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files)}))
